<?php
declare(strict_types=1);
namespace App\Controller;
use App\Entity\{Appointment,User};use App\Repository\TenantMembershipRepository;use App\Service\{ActiveTenantProvider,TenantMailer};use Doctrine\ORM\EntityManagerInterface;use Symfony\Bundle\SecurityBundle\Security;use Symfony\Component\HttpFoundation\{JsonResponse,Request};use Symfony\Component\Mime\Email;use Symfony\Component\Routing\Attribute\Route;
final class ApiAdminAppointmentController{public function __construct(private readonly EntityManagerInterface $em,private readonly ActiveTenantProvider $tenant,private readonly TenantMembershipRepository $memberships,private readonly Security $security,private readonly TenantMailer $mailer,private readonly string $mailFrom){} #[Route('/api/v1/admin/appointments',methods:['GET'])] public function list(Request $r):JsonResponse{if(!$this->admin())return new JsonResponse(['message'=>'Forbidden'],403);$qb=$this->em->createQueryBuilder()->select('a')->from(Appointment::class,'a')->where('a.tenant=:tenant')->setParameter('tenant',$this->tenant->get())->orderBy('a.startsAt','ASC');return new JsonResponse(['appointments'=>array_map(fn(Appointment $a)=>$this->data($a),$qb->getQuery()->getResult())]);} #[Route('/api/v1/admin/appointments/{id}/cancel',methods:['POST'])] public function cancel(int $id,Request $r):JsonResponse{if(!$this->admin())return new JsonResponse(['message'=>'Forbidden'],403);$a=$this->em->getRepository(Appointment::class)->find($id);if(!$a instanceof Appointment)return new JsonResponse(['message'=>'Nicht gefunden.'],404);$a->cancel();$this->em->flush();if(($r->toArray()['notifyCustomer']??true)===true){try{$this->mailer->send($this->tenant->get(),(new Email())->from($this->mailFrom)->to($a->getCustomer()->getEmail())->subject('Ihr Termin wurde storniert')->text('Ihr Termin für '.$a->getType()->getTitle().' am '.$a->getStartsAt()->format('d.m.Y H:i').' Uhr wurde storniert.'),'appointment_cancelled');}catch(\Throwable){}}return new JsonResponse(['appointment'=>$this->data($a)]);}private function data(Appointment $a):array{return['id'=>$a->getId(),'customer'=>$a->getCustomer()->getDisplayName(),'type'=>$a->getType()->getTitle(),'resource'=>$a->getResource()->getName(),'startsAt'=>$a->getStartsAt()->format(DATE_ATOM),'endsAt'=>$a->getEndsAt()->format(DATE_ATOM),'status'=>$a->getStatus()];}private function admin():bool{$u=$this->security->getUser();if(!$u instanceof User)return false;$m=$this->memberships->findForUserAndTenant($u,$this->tenant->get());return $m&&[]!==array_intersect(['ROLE_TENANT_STAFF','ROLE_TENANT_ADMIN'],$m->getRoles());}}
